.msg-me .msg-transfer-card .msg-transfer-content::after,
.bubble-me-custom .msg-transfer-card .msg-transfer-content::after{content:var(--transfer-me-remark)!important;}
.msg-them .msg-transfer-card .msg-transfer-content::after,
.bubble-them-custom .msg-transfer-card .msg-transfer-content::after{content:var(--transfer-them-remark)!important;}
.msg-me .msg-transfer-card.msg-transfer-success,
.msg-them .msg-transfer-card.msg-transfer-success,
.bubble-me-custom .msg-transfer-card.msg-transfer-success,
.bubble-them-custom .msg-transfer-card.msg-transfer-success{
  background:var(--transfer-card-bg-received)!important;
  background-color:var(--transfer-card-bg-received)!important;
}
.msg-transfer-card.msg-transfer-success .msg-transfer-icon{background-image:var(--transfer-icon-received)!important;}
.msg-me .msg-transfer-card.msg-transfer-success .msg-transfer-content::after,
.bubble-me-custom .msg-transfer-card.msg-transfer-success .msg-transfer-content::after{content:"已收款"!important;}
.msg-them .msg-transfer-card.msg-transfer-success .msg-transfer-content::after,
.bubble-them-custom .msg-transfer-card.msg-transfer-success .msg-transfer-content::after{content:"已被接受"!important;}
.msg-me .msg-transfer-card.msg-transfer-rejected,
.msg-them .msg-transfer-card.msg-transfer-rejected,
.bubble-me-custom .msg-transfer-card.msg-transfer-rejected,
.bubble-them-custom .msg-transfer-card.msg-transfer-rejected{
  background:var(--transfer-card-bg-received)!important;
  background-color:var(--transfer-card-bg-received)!important;
}
.msg-transfer-card.msg-transfer-rejected .msg-transfer-icon{background-image:var(--transfer-icon-returned)!important;}
.msg-me .msg-transfer-card.msg-transfer-rejected .msg-transfer-content::after,
.bubble-me-custom .msg-transfer-card.msg-transfer-rejected .msg-transfer-content::after{content:"已被退还"!important;}
.msg-them .msg-transfer-card.msg-transfer-rejected .msg-transfer-content::after,
.bubble-them-custom .msg-transfer-card.msg-transfer-rejected .msg-transfer-content::after{content:"已退还"!important;}
.msg-me .msg-transfer-card.msg-transfer-expired-card,
.msg-them .msg-transfer-card.msg-transfer-expired-card,
.bubble-me-custom .msg-transfer-card.msg-transfer-expired-card,
.bubble-them-custom .msg-transfer-card.msg-transfer-expired-card{
  background:var(--transfer-card-bg-expired)!important;
  background-color:var(--transfer-card-bg-expired)!important;
}
.msg-transfer-card.msg-transfer-expired-card .msg-transfer-icon{background-image:var(--transfer-icon-expired)!important;}
.msg-me .msg-transfer-card.msg-transfer-expired-card .msg-transfer-content::after,
.bubble-me-custom .msg-transfer-card.msg-transfer-expired-card .msg-transfer-content::after{content:"已过期"!important;}
.msg-them .msg-transfer-card.msg-transfer-expired-card .msg-transfer-content::after,
.bubble-them-custom .msg-transfer-card.msg-transfer-expired-card .msg-transfer-content::after{content:"已过期"!important;}
.msg-transfer-card.msg-transfer-expired-card .msg-transfer-expiry{display:none!important;}
.msg-me .msg-transfer-card::after,
.bubble-me-custom .msg-transfer-card::after,
.msg-them .msg-transfer-card::after,
.bubble-them-custom .msg-transfer-card::after{
  content:""!important;
  display:block!important;
  position:absolute!important;
  top:var(--bubble-tail-top)!important;
  width:var(--bubble-tail-width)!important;
  height:var(--bubble-tail-height)!important;
  border-radius: 2px !important;
  transform:rotate(45deg)!important;
  z-index:-1!important;
  pointer-events:none!important;
  background:var(--transfer-card-bg)!important;
}
.msg-me .msg-transfer-card::after,
.bubble-me-custom .msg-transfer-card::after{
  right:var(--bubble-me-tail-right)!important;
  left:auto!important;
}
.msg-them .msg-transfer-card::after,
.bubble-them-custom .msg-transfer-card::after{
  left:var(--bubble-them-tail-left)!important;
  right:auto!important;
}
.msg-me .msg-transfer-card.msg-transfer-success::after,
.msg-them .msg-transfer-card.msg-transfer-success::after,
.bubble-me-custom .msg-transfer-card.msg-transfer-success::after,
.bubble-them-custom .msg-transfer-card.msg-transfer-success::after,
.msg-me .msg-transfer-card.msg-transfer-rejected::after,
.msg-them .msg-transfer-card.msg-transfer-rejected::after,
.bubble-me-custom .msg-transfer-card.msg-transfer-rejected::after,
.bubble-them-custom .msg-transfer-card.msg-transfer-rejected::after{background:var(--transfer-card-bg-received)!important;}
.msg-me .msg-transfer-card.msg-transfer-expired-card::after,
.msg-them .msg-transfer-card.msg-transfer-expired-card::after,
.bubble-me-custom .msg-transfer-card.msg-transfer-expired-card::after,
.bubble-them-custom .msg-transfer-card.msg-transfer-expired-card::after{background:var(--transfer-card-bg-expired)!important;}
.bubble-me-custom:has(.msg-transfer-card)::before,
.bubble-them-custom:has(.msg-transfer-card)::before{display:none!important;}

