}
.nuo-thinking-btn .nuo-thinking-arrow,
.nuo-thinking-btn .nuo-thinking-icon,
.nuo-thinking-btn .nuo-thinking-label{
  display:none !important;
}
.nuo-thinking-btn::before{
  content:"" !important;
  position:absolute !important;
  inset:0 !important;
  width:auto !important;
  height:auto !important;
  opacity:1 !important;
  border-radius:50% !important;
  background:
    radial-gradient(circle at 21.9% 16.5%, var(--think-spin-color) calc(var(--think-spin-line) / 2), transparent calc(var(--think-spin-line) / 2 + 0.6px)),
    conic-gradient(from 0deg, transparent 0deg, var(--think-spin-color) 320deg, transparent 320.5deg) !important;
  -webkit-mask:radial-gradient(farthest-side, transparent calc(100% - var(--think-spin-line)), #000 calc(100% - var(--think-spin-line) + 0.6px));
  mask:radial-gradient(farthest-side, transparent calc(100% - var(--think-spin-line)), #000 calc(100% - var(--think-spin-line) + 0.6px));
  animation:wx-think-spin var(--think-spin-speed) linear infinite !important;
  pointer-events:none !important;
}
.nuo-thinking-btn::after{
  content:"" !important;
  position:absolute !important;
  inset:-10px !important;
  background:transparent !important;
  border:none !important;
  opacity:1 !important;
}
.nuo-thinking-btn.is-open::before{
  animation:none !important;
  transform:none !important;
}
:has(> .nuo-thinking-wrap){
