    radial-gradient(circle 1.8px at calc(100% - 5px) 50%, var(--think-card-dots) 98%, transparent 100%) no-repeat,
    radial-gradient(circle 1.8px at calc(100% - 12px) 50%, var(--think-card-dots) 98%, transparent 100%) no-repeat,
    radial-gradient(circle 1.8px at calc(100% - 19px) 50%, var(--think-card-dots) 98%, transparent 100%) no-repeat,
