/* =========================================================
   腾讯地图位置卡片（完整模块）
   图标：内嵌 SVG，红蓝指南针造型；不依赖外部图片链接
   用法：替换原 CSS 中“🌟 位置卡片”这一整段即可。
   其他聊天样式无需修改。
   ========================================================= */
:root {
  --loc-card-width: 258px;
  --loc-card-bg: #ffffff;
  --loc-card-radius: 6px;
  --loc-title-color: #111111;
  --loc-title-size: 14px;
  --loc-addr-color: #8a8a8a;
  --loc-addr-size: 11px;
  --loc-map-height: 90px;
  --loc-map-radius: 4px;
  --loc-map-bg: #c9ecaa;
  --loc-pin-color: #07c160;
  --loc-pin-inner: #ffffff;
  --loc-attr-color: #222222;

  /* 腾讯地图红蓝指南针小图标（参照你提供的 App 图标简化绘制） */
