body.dark-mode {
  --loc-card-bg: #2c2c2e;
  --loc-title-color: #f2f2f2;
  --loc-addr-color: #9a9a9e;
  --loc-map-bg: #3a4a3a;
  --loc-pin-inner: #ffffff;
  --loc-attr-color: #222222;
}

.msg-loc-card {
  position: relative !important;
  display: flex !important;
  flex-direction: column !important;
  box-sizing: border-box !important;
  width: var(--loc-card-width) !important;
  max-width: 100% !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 11px 5px 5px !important;
  background: var(--loc-card-bg) !important;
  background-image: none !important;
  border: none !important;
  border-radius: var(--loc-card-radius) !important;
  box-shadow: none !important;
  overflow: visible !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* 卡片小尾巴 */
.msg-loc-card::before {
  content: none !important;
  display: none !important;
}
.msg-loc-card::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  top: 15px !important;
  width: 9px !important;
  height: 9px !important;
  background: var(--loc-card-bg) !important;
  border-radius: 2px !important;
  transform: rotate(45deg) !important;
  pointer-events: none !important;
}
.msg-me .msg-loc-card::after,
.bubble-me-custom .msg-loc-card::after {
  right: -4px !important;
  left: auto !important;
}
.msg-them .msg-loc-card::after,
.bubble-them-custom .msg-loc-card::after {
  left: -4px !important;
  right: auto !important;
}

/* 头部文字区 */
.msg-loc-card .msg-loc-header,
.msg-loc-card .msg-loc-info {
  order: 1 !important;
  display: block !important;
  margin: 0 !important;
  padding: 0 !important;
  background: none !important;
  border: none !important;
}
.msg-loc-card .msg-loc-header :is(svg, img, [class*="icon"]) {
  display: none !important;
}
.msg-loc-card .msg-loc-name {
  order: 1 !important;
  display: block !important;
  margin: 0 0 6px !important;
  padding: 0 5px !important;
  color: var(--loc-title-color) !important;
  font-size: var(--loc-title-size) !important;
  font-weight: 700 !important;
  line-height: 1.4 !important;
  letter-spacing: .5px !important;
  text-align: left !important;
  white-space: normal !important;
  word-break: break-all !important;
}
.msg-loc-card .msg-loc-address {
  order: 2 !important;
  display: block !important;
  margin: 0 !important;
  padding: 0 5px !important;
  color: var(--loc-addr-color) !important;
  font-size: var(--loc-addr-size) !important;
  font-weight: 700 !important;
  line-height: 1.4 !important;
  text-align: left !important;
  white-space: normal !important;
  word-break: break-all !important;
}
.msg-loc-card .msg-loc-dist,
.msg-loc-card .msg-loc-approx,
.msg-loc-card .msg-loc-footer,
.msg-loc-card .msg-loc-footer-text {
  display: none !important;
}

/* 地图区底框 */
.msg-loc-card .msg-loc-map {
  order: 3 !important;
  position: relative !important;
  box-sizing: border-box !important;
  flex: none !important;
  width: 100% !important;
  height: var(--loc-map-height) !important;
  min-height: 0 !important;
  margin: 10px 0 0 !important;
  border: none !important;
  border-radius: var(--loc-map-radius) !important;
  box-shadow: none !important;
  overflow: hidden !important;
  background: var(--loc-map-bg) !important;
}

/* 真实地图层防挤压/防灰屏 */
.msg-loc-card .msg-loc-map.is-real .rmap,
.msg-loc-card .msg-loc-map.is-real .rmap-layer {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 100% !important;
  display: block !important;
}
.msg-loc-card .msg-loc-map.is-real .rmap-tile,
.msg-loc-card .msg-loc-map.is-real img {
  max-width: none !important;
  max-height: none !important;
  width: auto !important;
  height: auto !important;
  object-fit: fill !important;
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
  filter: none !important;
  border-radius: 0 !important;
}

/* 假地图底部：腾讯地图字样 + 红蓝指南针图标 */
.msg-loc-card .msg-loc-map:not(.is-real) :is(.msg-loc-grid, .msg-loc-grid-h, .msg-loc-grid-v) {
  opacity: .45 !important;
}
.msg-loc-card .msg-loc-map:not(.is-real)::after {
  content: "腾讯地图" !important;
  position: absolute !important;
  left: 5px !important;
  bottom: 3px !important;
  padding-left: calc(var(--loc-attr-icon-size) + var(--loc-attr-icon-gap)) !important;
  font-size: 10px !important;
  line-height: 14px !important;
  color: var(--loc-attr-color) !important;
  background: var(--loc-attr-icon) no-repeat left center / var(--loc-attr-icon-size) var(--loc-attr-icon-size) !important;
  pointer-events: none !important;
}

/* 真实地图版权区：隐藏原版权内容，只保留自定义标志与文字 */
.msg-loc-card .rmap-attr {
  position: absolute !important;
  left: 5px !important;
  right: auto !important;
  bottom: 3px !important;
  top: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  font-size: 0 !important;
  line-height: 0 !important;
  color: transparent !important;
}
.msg-loc-card .rmap-attr * {
  display: none !important;
}
.msg-loc-card .rmap-attr::before {
  content: none !important;
  display: none !important;
}
.msg-loc-card .rmap-attr::after {
  content: "腾讯地图" !important;
  display: block !important;
  padding-left: calc(var(--loc-attr-icon-size) + var(--loc-attr-icon-gap)) !important;
  font-size: 10px !important;
  line-height: 14px !important;
  color: var(--loc-attr-color) !important;
  background: var(--loc-attr-icon) no-repeat left center / var(--loc-attr-icon-size) var(--loc-attr-icon-size) !important;
}

/* 隐藏多余地图元素 */
.msg-loc-card .rmap-ctrl,
.msg-loc-card .rmap-pin-label,
.msg-loc-card .rmap-pin-shadow,
.msg-loc-card .msg-loc-pin-shadow {
  display: none !important;
}

/* 绿色圆形定位针头部 */
.msg-loc-card :is(.rmap-pin-head, .msg-loc-pin-circle) {
  position: relative !important;
  display: block !important;
  box-sizing: border-box !important;
  width: 26px !important;
  height: 26px !important;
  margin: 0 0 16px !important;
  padding: 0 !important;
  background: var(--loc-pin-inner) !important;
  background-image: none !important;
  border: 8px solid var(--loc-pin-color) !important;
  border-radius: 50% !important;
  box-shadow: none !important;
  transform: none !important;
  rotate: none !important;
  animation: none !important;
  filter: none !important;
}
.msg-loc-card :is(.rmap-pin-head, .msg-loc-pin-circle) > * {
  display: none !important;
}
.msg-loc-card :is(.rmap-pin-head, .msg-loc-pin-circle)::before {
  content: none !important;
  display: none !important;
}

/* 绿色定位针尾巴 */
.msg-loc-card :is(.rmap-pin-head, .msg-loc-pin-circle)::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  left: 50% !important;
  top: calc(100% + 1px) !important;
  width: 4px !important;
  height: 17px !important;
  margin: 0 0 0 -2px !important;
  background: var(--loc-pin-color) !important;
  border: none !important;
  border-radius: 2px !important;
  transform: none !important;
}

/* 夜间真实地图压暗：保持原有处理 */
body.dark-mode .msg-loc-card .msg-loc-map.is-real {
  filter: brightness(0.6) contrast(1.1) !important;
}
:root {
  --cc-card-width: 490px;
  --cc-card-min-height: 112px;
  --cc-card-padding-x: 17px;
  --cc-card-padding-y: 10px;
  --cc-card-radius: 7px;
  --cc-card-bg: #ffffff;
  --cc-card-name: #191919;
  --cc-card-sign: #888888;
  --cc-card-foot: #777777;
  --cc-card-avatar-size: 67px;
  --cc-card-avatar-radius: 7px;
  --cc-card-content-gap: 18px;
  --cc-card-name-size: 21px;
  --cc-card-sign-size: 10px;
  --cc-card-foot-size: 13px;
  --cc-card-tail-size: 9px;
  --cc-card-tail-top: 29px;
  --cc-card-tail-color: var(--cc-card-bg);
  --cc-card-action-bg: #07c160;
  --cc-card-action-color: #ffffff;
}

/* 名片主体 */
.cc-card {
  position: relative !important;
  isolation: isolate !important;
  display: flex !important;
  flex-direction: column !important;
  box-sizing: border-box !important;
  width: min(var(--cc-card-width), calc(100vw - 112px)) !important;
  max-width: 100% !important;
  min-width: 0 !important;
  min-height: var(--cc-card-min-height) !important;
  margin: 0 !important;
  padding: var(--cc-card-padding-y) var(--cc-card-padding-x) 8px !important;
  overflow: visible !important;
  background: var(--cc-card-bg) !important;
  background-image: none !important;
  border: none !important;
  border-radius: var(--cc-card-radius) !important;
  box-shadow: none !important;
  color: var(--cc-card-name) !important;
}

/* 右侧指向头像的小尖角 */
.cc-card::after {
  content: "" !important;
  position: absolute !important;
  z-index: 0 !important;
  top: var(--cc-card-tail-top) !important;
  right: calc(var(--cc-card-tail-size) / -2) !important;
  display: block !important;
  width: var(--cc-card-tail-size) !important;
  height: var(--cc-card-tail-size) !important;
  background: var(--cc-card-bg) !important;
  border: none !important;
  border-radius: 2px !important;
  transform: rotate(45deg) !important;
  box-shadow: none !important;
  pointer-events: none !important;
}

/* 上半部：头像、名字、签名 */
.cc-card .cc-top {
  position: relative !important;
  z-index: 1 !important;
  display: grid !important;
  grid-template-columns: var(--cc-card-avatar-size) minmax(0, 1fr) !important;
  grid-template-rows: auto auto !important;
  align-content: center !important;
  align-items: center !important;
  column-gap: var(--cc-card-content-gap) !important;
  row-gap: 5px !important;
  width: 100% !important;
  min-width: 0 !important;
  min-height: var(--cc-card-avatar-size) !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
}

/* 头像；兼容头像为 img 或内部包含 img 的容器 */
.cc-card .cc-avatar {
  position: relative !important;
  grid-column: 1 !important;
  grid-row: 1 / span 2 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  box-sizing: border-box !important;
  flex: none !important;
  width: var(--cc-card-avatar-size) !important;
  height: var(--cc-card-avatar-size) !important;
  min-width: var(--cc-card-avatar-size) !important;
  min-height: var(--cc-card-avatar-size) !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  background: #f1eee9 !important;
  border: none !important;
  border-radius: var(--cc-card-avatar-radius) !important;
  color: #555555 !important;
  font-size: 25px !important;
  font-weight: 600 !important;
  line-height: 1 !important;
  text-align: center !important;
}

.cc-card .cc-avatar img,
.cc-card img.cc-avatar {
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  min-width: 100% !important;
  min-height: 100% !important;
  max-width: none !important;
  max-height: none !important;
  margin: 0 !important;
  padding: 0 !important;
  object-fit: cover !important;
  object-position: center !important;
  border: 0 !important;
  border-radius: inherit !important;
  box-shadow: none !important;
}

/* 清除头像下方可能由原始组件带来的细线、伪元素和阴影 */
.cc-card .cc-avatar,
.cc-card .cc-avatar img,
.cc-card img.cc-avatar {
  border-bottom: 0 !important;
  box-shadow: none !important;
  outline: none !important;
}
.cc-card .cc-avatar::before,
.cc-card .cc-avatar::after,
.cc-card .cc-top::before,
.cc-card .cc-top::after,
.cc-card .cc-avatar hr,
.cc-card .cc-top hr {
  content: none !important;
  display: none !important;
  border: 0 !important;
  box-shadow: none !important;
}

/* 名字：以头像中心线为基准，上下居中 */
.cc-card .cc-name {
  position: absolute !important;
  z-index: 2 !important;
  left: calc(var(--cc-card-avatar-size) + var(--cc-card-content-gap)) !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  display: block !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  color: var(--cc-card-name) !important;
  -webkit-text-fill-color: var(--cc-card-name) !important;
  font-size: var(--cc-card-name-size) !important;
  font-weight: 700 !important;
  line-height: 1.25 !important;
  letter-spacing: 0 !important;
  text-align: left !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;
}

/* 个性签名：保留在名字下方，不改变名字的垂直居中位置 */
.cc-card .cc-sign {
  position: absolute !important;
  left: calc(var(--cc-card-avatar-size) + var(--cc-card-content-gap)) !important;
  right: 0 !important;
  bottom: 0 !important;
  display: block !important;
  min-width: 0 !important;
  margin: 2px 0 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  color: var(--cc-card-sign) !important;
  -webkit-text-fill-color: var(--cc-card-sign) !important;
  font-size: var(--cc-card-sign-size) !important;
  font-weight: 400 !important;
  line-height: 1.4 !important;
  text-align: left !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;
}

/* 名字与签名均限制在头像右侧内容区 */
.cc-card .cc-name,
.cc-card .cc-sign {
  max-width: calc(100% - var(--cc-card-avatar-size) - var(--cc-card-content-gap)) !important;
}

/* 底部“个人名片” */
.cc-card .cc-foot {
  position: relative !important;
  z-index: 1 !important;
  display: flex !important;
  align-items: center !important;
  min-width: 0 !important;
  margin: auto 0 0 !important;
  padding: 5px 0 0 !important;
  color: var(--cc-card-foot) !important;
  -webkit-text-fill-color: var(--cc-card-foot) !important;
  font-size: var(--cc-card-foot-size) !important;
  font-weight: 600 !important;
  line-height: 1.25 !important;
  letter-spacing: 0 !important;
  text-align: left !important;
}

/* 已加为好友状态 */
.cc-card .cc-added {
  position: relative !important;
  z-index: 1 !important;
  display: inline-flex !important;
  align-items: center !important;
  width: fit-content !important;
  max-width: 100% !important;
  margin: 8px 0 0 auto !important;
  padding: 0 !important;
  color: var(--cc-card-foot) !important;
  -webkit-text-fill-color: var(--cc-card-foot) !important;
  font-size: 11px !important;
  font-weight: 400 !important;
  line-height: 1.4 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* 加好友按钮 */
.cc-card .cc-add-btn {
  position: relative !important;
  z-index: 1 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  min-width: 54px !important;
  min-height: 25px !important;
  margin: 8px 0 0 auto !important;
  padding: 3px 10px !important;
  color: var(--cc-card-action-color) !important;
  -webkit-text-fill-color: var(--cc-card-action-color) !important;
  font-size: 11px !important;
  font-weight: 500 !important;
  line-height: 1.2 !important;
  background: var(--cc-card-action-bg) !important;
  border: none !important;
  border-radius: 4px !important;
  box-shadow: none !important;
  cursor: pointer !important;
}

.cc-card .cc-add-btn:active {
  opacity: .82 !important;
}

/* 夜间模式 */
@media (prefers-color-scheme: dark) {
  body {
    --cc-card-bg: #2c2c2e;
    --cc-card-name: #f2f2f2;
    --cc-card-sign: #a0a0a6;
    --cc-card-foot: #a0a0a6;
  }
}

/* 兼容页面自身的夜间模式开关 */
body.dark-mode {
  --cc-card-bg: #2c2c2e;
  --cc-card-name: #f2f2f2;
  --cc-card-sign: #a0a0a6;
  --cc-card-foot: #a0a0a6;
}

/* 小屏幕适配 */
@media (max-width: 520px) {
  :root {
    --cc-card-min-height: 92px;
    --cc-card-padding-x: 11px;
    --cc-card-padding-y: 8px;
    --cc-card-avatar-size: 45px;
    --cc-card-content-gap: 11px;
    --cc-card-name-size: 14px;
    --cc-card-sign-size: 10px;
    --cc-card-foot-size: 11px;
    --cc-card-tail-top: 23px;
    --cc-card-tail-size: 9px;
  }

  .cc-card {
    width: min(var(--cc-card-width), calc(100vw - 104px)) !important;
    padding-bottom: 7px !important;
  }

  .cc-card .cc-foot {
    padding-top: 4px !important;
  }
}

/* =========================================================
   v2.3 最终修正：彻底移除名片横线 + 夜间小角同步变暗
   ========================================================= */
.cc-card,
.cc-card .cc-top,
.cc-card .cc-avatar,
.cc-card .cc-avatar img,
.cc-card img.cc-avatar,
.cc-card .cc-name,
.cc-card .cc-sign,
.cc-card .cc-foot,
.cc-card .cc-added,
.cc-card .cc-add-btn {
  border-top: 0 !important;
  border-bottom: 0 !important;
  box-shadow: none !important;
  outline: none !important;
}

/* 分隔线可能来自原组件的 hr、分割元素或伪元素 */
.cc-card hr,
.cc-card [role="separator"],
.cc-card [class~="divider"],
.cc-card [class~="separator"],
.cc-card [class*="divider"],
.cc-card [class*="separator"],
.cc-card::before,
.cc-card .cc-top::before,
.cc-card .cc-top::after,
.cc-card .cc-avatar::before,
.cc-card .cc-avatar::after,
.cc-card .cc-foot::before,
.cc-card .cc-foot::after {
  display: none !important;
  content: none !important;
  height: 0 !important;
  min-height: 0 !important;
  border: 0 !important;
  background: none !important;
  box-shadow: none !important;
}

/* 小角直接读取卡片背景变量，避免根节点变量固定成白色 */
.cc-card::after {
  background: var(--cc-card-bg) !important;
  background-color: var(--cc-card-bg) !important;
  background-image: none !important;
  border: 0 !important;
  box-shadow: none !important;
}

/* 系统夜间模式 */
@media (prefers-color-scheme: dark) {
  body .cc-card::after {
    background: #2c2c2e !important;
    background-color: #2c2c2e !important;
  }
