  --sim-expand-color: #939494;
}

/* 让内容栈成为定位参照 */
.msg-me .msg-content-stack:has(.msg-sim-card),
.msg-them .msg-content-stack:has(.msg-sim-card) {
  position: relative !important;
  overflow: visible !important;
}

/* 公共样式：对方用 ::after，我方用 ::before */
.msg-them .msg-content-stack:has(.msg-sim-card)::after,
.msg-me .msg-content-stack:has(.msg-sim-card)::before {
  content: "展开3" !important;
