  --input-area-bg: #ffffff;
  --input-area-bg-image: none;
  --input-area-blur: 0px;
  /* 输入文字 */
  --input-box-font-size: 13px;
  --input-box-color: #bdbdbd;
  --input-box-placeholder: #bdbdbd;
  --input-caret-color: #bdbdbd;

  --ph-left: 30px;        /* 占位文案 + 输入文字的起点,越大越靠右 */
  --input-h: 20px;        /* 输入区固定高度,写满后出滑动条 */
}
/* ① 底栏白底 */
.chat-detail-screen .input-area-custom {
  background: #ffffff !important;
  background-image: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
/* ③ 占位文案:右移,字号和输入文字一致 */
.chat-detail-screen .input-area-custom .input-action-bar-custom:has(.input-box-custom:placeholder-shown)::before {
  left: calc(var(--ph-left) + 6px) !important;
  font-size: 13px !important;
  transform: translateY(-50%) !important;
  color: #bdbdbd !important;
}
/* ④ Send 药丸:不被容器拉高,上下压扁 */
.chat-detail-screen .input-area-custom .send-btn-custom {
  align-self: center !important;
  height: 22px !important;
  min-height: 0 !important;
  max-height: 22px !important;
  width: auto !important;
  aspect-ratio: auto !important;
  box-sizing: border-box !important;
  padding: 0 14px !important;
  font-size: 11px !important;
  line-height: 22px !important;
}
/* ====== 输入框:自适应高度 + 滚动条 ====== */

#chat-detail-screen .input-box-custom {
  min-height: 32px !important;
  max-height: 120px !important;
  height: auto !important;
  overflow-y: auto !important;
  overflow-x: hidden !important;
  word-wrap: break-word !important;
  white-space: pre-wrap !important;
