}
#chat-detail-screen .input-box-custom::placeholder {
  color: rgba(192,128,152,0.4) !important;
  font-size: 13px !important;
}
#chat-detail-screen .input-box-custom:focus,
#chat-detail-screen .input-box-custom:active {
  color: #bdbdbd !important;
  font-size: 13px !important;
}
.chat-detail-screen .input-btn-mic {
  opacity: 0 !important;
  pointer-events: auto !important;
  cursor: pointer !important;
  width: 32px !important;
  height: 32px !important;
  flex-shrink: 0 !important;
}
.chat-detail-screen .input-btn-sticker {
  opacity: 0 !important;
  pointer-events: auto !important;
